Types to avoid this in the future:

{noformat}interface PspRemovePaymentInstrumentRequestGeneral {
    payment_user_id: number;
    instrument_type: Exclude<PaymentInstrumentType, PaymentInstrumentType.PROCESSOUT>;
    instrument_reference: string;
}

interface PspRemovePaymentInstrumentRequestProcessout {
    payment_user_id: number;
    user_metadata: PaymentUserMetadata;
    instrument_type: PaymentInstrumentType.PROCESSOUT;
    instrument_reference: string;
}

export type PspRemovePaymentInstrumentRequest =
    | PspRemovePaymentInstrumentRequestGeneral
    | PspRemovePaymentInstrumentRequestProcessout;{noformat}

